15	
16	class MockChatRemoteDataSource extends Mock implements ChatRemoteDataSource {}
17	
18	class MockSessionRepository extends Mock implements SessionRepository {}
19	
20	class MockChatLocalCache extends Mock implements ChatLocalCache {}
21	
22	ChatSession _buildSession({String id = 's1'}) => ChatSession(
23	  id: id,
24	  title: 'title',
25	  personaSnapshot: ChatPersona.analitico,
26	  userMessageCount: 1,
27	  lastUserMessageAt: DateTime(2026, 1, 1),
28	  createdAt: DateTime(2026, 1, 1),
29	  updatedAt: DateTime(2026, 1, 1),
30	);
31	
32	ChatMessage _buildMessage({String id = 'm1'}) => ChatMessage(
33	  id: id,
34	  sessionId: 's1',
35	  role: ChatRole.user,
36	  content: 'hi',
37	  seq: 0,
38	  status: ChatMessageStatus.complete,
39	  retryCount: 0,
40	  createdAt: DateTime(2026, 1, 1),
41	);
42	
43	Session _buildAuthSession() => const Session(
44	  accessToken: 'token',
45	  refreshToken: 'refresh',
46	  expiresAt: 0,
47	  tokenType: 'bearer',
48	  account: Account(id: 'acc-1', email: 'test@example.com'),
49	);
50	
51	const _authExpired = AuthExpiredFailure(message: 'expired', requestId: '');
52	
53	void main() {
54	  late MockChatRemoteDataSource remoteDataSource;
55	  late MockSessionRepository sessionRepository;
56	  late MockChatLocalCache localCache;
57	  late ChatRepositoryImpl repository;
58	
59	  setUpAll(() {
60	    registerFallbackValue(<ChatSession>[]);
61	  });
62	
63	  setUp(() {
64	    remoteDataSource = MockChatRemoteDataSource();
65	    sessionRepository = MockSessionRepository();
66	    localCache = MockChatLocalCache();
67	    when(() => localCache.readSessions()).thenAnswer((_) async => const []);
68	    when(() => localCache.readAllMessages()).thenAnswer((_) async => const {});
69	    when(() => localCache.readSavedMessageEntryIds()).thenAnswer((_) async => const {});
70	    when(() => localCache.writeSessions(any())).thenAnswer((_) async {});
71	    when(
72	      () => localCache.writeMessagesForSession(any(), any()),
73	    ).thenAnswer((_) async {});
74	    when(
75	      () => localCache.writeSavedMessageEntryIds(any()),
76	    ).thenAnswer((_) async {});
77	    repository = ChatRepositoryImpl(
78	      remoteDataSource,
79	      sessionRepository: sessionRepository,
80	      localCache: localCache,
81	    );
82	  });
83	
84	  test(
85	    '#1 createSession upserts the parsed session into cachedSessions',
86	    () async {
87	      final session = _buildSession();
88	      when(
89	        () => remoteDataSource.createSession(title: any(named: 'title')),
90	      ).thenAnswer((_) async => Right(session));
91	
92	      final result = await repository.createSession(title: 'Ansiedade');
93	
94	      expect(result, Right<Failure, ChatSession>(session));
95	      expect(repository.cachedSessions, [session]);
96	    },
97	  );
98	
99	  test(
100	    '#1b cachedSessions stays ordered by lastUserMessageAt descending after a '
101	    'newer session is created (FR-008) — not merely appended to the end',
102	    () async {
103	      final older = ChatSession(
104	        id: 's-old',
105	        title: 'older',
106	        personaSnapshot: ChatPersona.analitico,
107	        userMessageCount: 1,
108	        lastUserMessageAt: DateTime(2026, 1, 1),
109	        createdAt: DateTime(2026, 1, 1),
110	        updatedAt: DateTime(2026, 1, 1),
111	      );
112	      final newer = ChatSession(
113	        id: 's-new',
114	        title: 'newer',
115	        personaSnapshot: ChatPersona.analitico,
116	        userMessageCount: 1,
117	        lastUserMessageAt: DateTime(2026, 1, 2),
118	        createdAt: DateTime(2026, 1, 2),
119	        updatedAt: DateTime(2026, 1, 2),
120	      );
121	      when(() => localCache.readSessions()).thenAnswer((_) async => [older]);
122	      when(
123	        () => remoteDataSource.createSession(title: any(named: 'title')),
124	      ).thenAnswer((_) async => Right(newer));
125	
126	      // `createSession` lazily loads `older` from the local cache first (as
127	      // a real app restart would), then upserts `newer` — the most recently
128	      // active session must sort to the front even though it was upserted
129	      // last.
130	      await repository.createSession(title: 'Nova conversa');
131	
132	      expect(repository.cachedSessions.map((s) => s.id), ['s-new', 's-old']);
133	    },
134	  );
