136	  test(
137	    '#2 listSessions: AuthExpiredFailure on first call, success on retry -> '
138	    'exactly one refresh, one more listSessions call, final Right',
139	    () async {
140	      final page = ChatSessionsPage(sessions: [_buildSession()], nextCursor: null);
141	      var callCount = 0;
142	      when(
143	        () => remoteDataSource.listSessions(
144	          cursor: any(named: 'cursor'),
145	          limit: any(named: 'limit'),
146	        ),
147	      ).thenAnswer((_) async {
148	        callCount++;
149	        return callCount == 1 ? const Left(_authExpired) : Right(page);
150	      });
151	      when(() => sessionRepository.refresh()).thenAnswer((_) async => Right(_buildAuthSession()));
152	
