      const a = InsightTrigger(
        type: InsightTriggerType.messageCount,
        triggerKey: 'message_count:5',
      );
      const b = InsightTrigger(
        type: InsightTriggerType.messageCount,
        triggerKey: 'message_count:10',
      );
      expect(a, isNot(b));
    });

