134	  /// One independent request/response per message — never involves
135	  /// `_turnGeneration`, never touches `awaitingResponse`/`messages`, so a
136	  /// save can never block the rest of the screen (FR-006).
137	  Future<void> _onBookmarkTapped(
138	    BookmarkTapped event,
139	    Emitter<ChatState> emit,
140	  ) async {
141	    final current = state;
142	    if (current is! ChatReady) return;
143	
144	    final index = current.messages.indexWhere((m) => m.id == event.messageId);
145	    if (index == -1) return;
146	    final message = current.messages[index];
147	
148	    if (message.role != ChatRole.user) return; // FR-001, defensive
149	    if (message.isOptimistic) return; // research.md R6
150	
151	    final currentStatus = current.bookmarkStatusFor(message.id);
152	    if (currentStatus == BookmarkStatus.saving || currentStatus == BookmarkStatus.saved) {
153	      return; // FR-003/FR-007
154	    }
155	
156	    emit(
157	      current.copyWith(
158	        bookmarks: {...current.bookmarks, message.id: BookmarkStatus.saving},
159	      ),
160	    );
161	
162	    final created = await _createEntryUseCase(
163	      message.content,
164	      EntrySource.chat,
165	      chatMessageId: message.id,
166	      occurredAt: message.createdAt,
167	    );
168	
169	    final latest = state;
170	    if (latest is! ChatReady) return; // navigated away mid-save
171	
172	    await created.match(
173	      (failure) async {
174	        if (failure is AuthExpiredFailure) _reauthController.add(null); // research.md R9
175	        emit(
176	          latest.copyWith(
177	            bookmarks: {...latest.bookmarks, message.id: BookmarkStatus.error},
178	          ),
179	        );
180	      },
181	      (entry) async {
182	        await _chatRepository.recordMessageSaved(
183	          chatMessageId: message.id,
184	          entryId: entry.id,
185	        );
186	        final afterRecord = state;
187	        if (afterRecord is! ChatReady) return;
188	        emit(
189	          afterRecord.copyWith(
190	            bookmarks: {...afterRecord.bookmarks, message.id: BookmarkStatus.saved},
191	          ),
192	        );
193	      },
194	    );
195	  }
