206	  /// The shared fetch-with-cache-fallback path (Clarification 3).
207	  Future<void> _loadSession(
208	    String sessionId,
209	    Emitter<ChatState> emit, {
210	    required bool isOffline,
211	  }) async {
212	    final result = await _chatRepository.listMessages(sessionId);
213	    await result.match(
214	      (failure) async {
215	        if (failure is AuthExpiredFailure) _reauthController.add(null);
216	        final cached = _chatRepository.cachedMessages(sessionId);
217	        if (cached == null) {
218	          // Never opened while online — the "standard no-connection state"
219	          // instead of any content (Edge Cases).
220	          emit(
221	            ChatReady(
222	              sessionId: sessionId,
223	              messages: const [],
224	              isOffline: isOffline,
225	              awaitingResponse: false,
226	              loadFailure: failure,
227	            ),
228	          );
229	        } else {
230	          emit(
231	            ChatReady(
232	              sessionId: sessionId,
233	              messages: cached,
234	              isOffline: isOffline,
235	              awaitingResponse: false,
236	              bookmarks: _seedBookmarks(cached),
237	            ),
238	          );
239	        }
240	      },
241	      (messages) async {
242	        await _chatRepository.setLastActiveSessionId(sessionId);
243	        emit(
244	          ChatReady(
245	            sessionId: sessionId,
246	            messages: messages,
247	            isOffline: isOffline,
248	            awaitingResponse: false,
249	            bookmarks: _seedBookmarks(messages),
250	          ),
251	        );
252	      },
253	    );
254	  }
