256	  /// FR-008 — rebuilt from scratch on every `_loadSession` call (never
257	  /// incrementally patched): for every user message already recorded as
258	  /// saved (research.md R1), seed that id as `saved`; every other message is
259	  /// left absent, i.e. `idle`.
260	  Map<String, BookmarkStatus> _seedBookmarks(List<ChatMessage> messages) {
261	    final result = <String, BookmarkStatus>{};
262	    for (final m in messages) {
263	      if (m.role != ChatRole.user) continue;
264	      if (_chatRepository.savedEntryIdFor(m.id) != null) {
265	        result[m.id] = BookmarkStatus.saved;
266	      }
267	    }
268	    return result;
269	  }
