271	  Future<void> _onMessageSubmitted(
272	    MessageSubmitted event,
273	    Emitter<ChatState> emit,
274	  ) async {
275	    final current = state;
276	    if (current is! ChatReady || !current.canSend) return;
277	
278	    if (!await _connectivityChecker.hasConnection()) {
279	      // FR-012 — blocked client-side, never attempted. The composer's own
280	      // isOffline flag (R8's live stream) reflects this on its own shortly.
281	      return;
282	    }
283	
284	    final generation = ++_turnGeneration;
285	    final now = DateTime.now();
286	    final optimisticUser = ChatMessage(
287	      id: 'local-${now.microsecondsSinceEpoch}',
288	      sessionId: current.sessionId ?? '',
289	      role: ChatRole.user,
290	      content: event.text,
291	      seq: current.messages.length,
292	      status: ChatMessageStatus.complete,
293	      retryCount: 0,
294	      createdAt: now,
295	    );
296	    final optimisticAssistant = ChatMessage(
297	      id: 'local-${now.microsecondsSinceEpoch}-response',
298	      sessionId: current.sessionId ?? '',
299	      role: ChatRole.assistant,
300	      content: '',
301	      seq: current.messages.length + 1,
302	      status: ChatMessageStatus.streaming,
303	      retryCount: 0,
304	      createdAt: now,
305	    );
306	
307	    if (!_insightSuspended) {
308	      _insightMessageCount++;
309	      if (_insightMessageCount % 5 == 0) {
310	        _pendingInsightTrigger ??= InsightTrigger(
311	          type: InsightTriggerType.messageCount,
312	          triggerKey: InsightTriggerKeyBuilder.forMessageCount(_insightMessageCount),
313	        );
314	      }
315	    }
316	    _armInactivityTimer(); // FR-001b — resets "time since last message sent" now
317	
318	    emit(
319	      current.copyWith(
320	        messages: [...current.messages, optimisticUser, optimisticAssistant],
321	        awaitingResponse: true,
322	      ),
323	    );
324	
325	    String sessionId;
326	    if (current.sessionId == null) {
327	      final created = await _chatRepository.createSession(
328	        title: ChatTitleDeriver.derive(event.text),
329	      );
330	      if (generation != _turnGeneration) return;
331	      final maybeId = created.match((_) => null, (s) => s.id);
332	      if (maybeId == null) {
333	        final failure = created.getLeft().toNullable()!;
334	        await _failTurn(emit, current.sessionId ?? '', optimisticAssistant.id, failure);
335	        return;
336	      }
337	      sessionId = maybeId;
338	      await _chatRepository.setLastActiveSessionId(sessionId);
339	    } else {
340	      sessionId = current.sessionId!;
341	    }
342	
343	    final stream = _chatRepository.sendMessage(
344	      sessionId: sessionId,
345	      content: event.text,
346	    );
347	    await _consumeTurn(
348	      stream,
349	      emit,
350	      generation: generation,
351	      sessionId: sessionId,
352	      optimisticUserId: optimisticUser.id,
353	      optimisticAssistantId: optimisticAssistant.id,
354	    );
355	  }
