357	  Future<void> _onMessageRetryRequested(
358	    MessageRetryRequested event,
359	    Emitter<ChatState> emit,
360	  ) async {
361	    final current = state;
362	    if (current is! ChatReady || current.awaitingResponse) {
363	      return;
364	    }
365	    final index = current.messages.indexWhere(
366	      (m) =>
367	          m.role == ChatRole.assistant &&
368	          m.status == ChatMessageStatus.failed &&
369	          _userMessageIdFor(current.messages, m) == event.userMessageId,
370	    );
371	    if (index == -1) return;
372	    if (!await _connectivityChecker.hasConnection()) return; // FR-012
373	
374	    final userMessage = current.messages[index - 1];
375	    if (userMessage.isOptimistic) {
376	      // The turn's very first `createSession` call failed (FR-006) — there
377	      // is no persisted session/message yet for `retryMessage` to target, so
378	      // re-run the same lazy-creation path `_onMessageSubmitted` takes.
379	      await _retryLazySessionCreation(current, index, userMessage, emit);
380	      return;
381	    }
382	    if (current.sessionId == null) return;
383	
384	    final generation = ++_turnGeneration;
385	    final now = DateTime.now();
386	    final placeholder = ChatMessage(
387	      id: 'local-${now.microsecondsSinceEpoch}-retry',
388	      sessionId: current.sessionId!,
389	      role: ChatRole.assistant,
390	      content: '',
391	      seq: current.messages[index].seq,
392	      status: ChatMessageStatus.streaming,
393	      retryCount: current.messages[index].retryCount + 1,
394	      createdAt: now,
395	    );
396	    final updatedMessages = [...current.messages];
397	    updatedMessages[index] = placeholder;
398	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
399	
400	    final stream = _chatRepository.retryMessage(
401	      sessionId: current.sessionId!,
402	      userMessageId: event.userMessageId,
403	    );
404	    await _consumeTurn(
405	      stream,
406	      emit,
407	      generation: generation,
408	      sessionId: current.sessionId!,
409	      optimisticUserId: null,
410	      optimisticAssistantId: placeholder.id,
411	    );
412	  }
