414	  /// Retries a turn whose lazy `createSession` call (FR-010) itself failed
415	  /// before any session ever existed — reuses `createSession` +
416	  /// `sendMessage` with the original user message's own content, exactly as
417	  /// `_onMessageSubmitted` does for a brand-new conversation.
418	  Future<void> _retryLazySessionCreation(
419	    ChatReady current,
420	    int index,
421	    ChatMessage userMessage,
422	    Emitter<ChatState> emit,
423	  ) async {
424	    final generation = ++_turnGeneration;
425	    final now = DateTime.now();
426	    final placeholder = ChatMessage(
427	      id: 'local-${now.microsecondsSinceEpoch}-retry',
428	      sessionId: userMessage.sessionId,
429	      role: ChatRole.assistant,
430	      content: '',
431	      seq: current.messages[index].seq,
432	      status: ChatMessageStatus.streaming,
433	      retryCount: current.messages[index].retryCount + 1,
434	      createdAt: now,
435	    );
436	    final updatedMessages = [...current.messages];
437	    updatedMessages[index] = placeholder;
438	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
439	
440	    final created = await _chatRepository.createSession(
441	      title: ChatTitleDeriver.derive(userMessage.content),
442	    );
443	    if (generation != _turnGeneration) return;
444	    final maybeId = created.match((_) => null, (s) => s.id);
445	    if (maybeId == null) {
446	      final failure = created.getLeft().toNullable()!;
447	      await _failTurn(emit, userMessage.sessionId, placeholder.id, failure);
448	      return;
449	    }
450	    await _chatRepository.setLastActiveSessionId(maybeId);
451	
452	    final latest = state;
453	    if (latest is! ChatReady || generation != _turnGeneration) return;
454	    emit(latest.copyWith(sessionId: maybeId));
455	
456	    final stream = _chatRepository.sendMessage(
457	      sessionId: maybeId,
458	      content: userMessage.content,
459	    );
460	    await _consumeTurn(
461	      stream,
462	      emit,
463	      generation: generation,
464	      sessionId: maybeId,
465	      optimisticUserId: userMessage.id,
466	      optimisticAssistantId: placeholder.id,
467	    );
468	  }
