470	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
471	  /// and a retry.
472	  Future<void> _consumeTurn(
473	    Stream<Either<Failure, ChatStreamEvent>> stream,
474	    Emitter<ChatState> emit, {
475	    required int generation,
476	    required String sessionId,
477	    required String? optimisticUserId,
478	    required String optimisticAssistantId,
479	  }) async {
480	    var assistantId = optimisticAssistantId;
481	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
482	      stream,
483	      onData: (result) {
484	        final latest = state;
485	        if (generation != _turnGeneration || latest is! ChatReady) {
486	          return latest;
487	        }
488	        return result.match((failure) {
489	          if (failure is AuthExpiredFailure) _reauthController.add(null);
490	          return _applyFailure(latest, assistantId, failure);
491	        }, (event) => switch (event) {
492	          MessageCreated() => () {
493	            assistantId = event.assistantMessageId;
494	            return _reconcileIds(
495	              latest,
496	              optimisticUserId,
497	              event.userMessageId,
498	              optimisticAssistantId,
499	              event.assistantMessageId,
500	            );
501	          }(),
502	          ContextReceived() => latest,
503	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
504	          StreamDone(assistantMessageId: final id) =>
505	            _completeMessage(latest, id).copyWith(awaitingResponse: false),
506	        });
507	      },
508	    );
509	    await _reconcileSilentFailure(emit, sessionId, assistantId, generation);
510	    if (generation == _turnGeneration) await _onTurnResolved(sessionId, emit);
511	  }
512	
513	  /// A failure yielded as (or before) the stream's very first item leaves the
514	  /// bubble `failed` with empty content even though the backend may have
515	  /// kept generating in the background and already persisted the full
516	  /// answer by the time the stream closed (e.g. a transient network drop
517	  /// right after `message_created`, before any token arrives). One
518	  /// best-effort refetch here closes that gap without needing the user to
519	  /// leave and come back. Only acts on an empty-content failure — a failure
520	  /// after partial tokens (FR-005) is left exactly as the stream reported
521	  /// it. Note this is a best-effort recovery for a genuinely slow backend,
522	  /// not a substitute for parsing the stream correctly in the first place —
523	  /// it loses the race whenever the backend is still generating (slow/live
524	  /// answers can take several seconds longer than this one refetch waits
525	  /// for).
526	  Future<void> _reconcileSilentFailure(
527	    Emitter<ChatState> emit,
528	    String sessionId,
529	    String assistantId,
530	    int generation,
531	  ) async {
532	    final seeded = state;
533	    if (seeded is! ChatReady || generation != _turnGeneration) return;
534	    final index = seeded.messages.indexWhere((m) => m.id == assistantId);
535	    if (index == -1) return;
536	    final message = seeded.messages[index];
537	    if (message.status != ChatMessageStatus.failed || message.content.isNotEmpty) {
538	      return;
539	    }
540	
541	    final result = await _chatRepository.listMessages(sessionId);
542	    if (generation != _turnGeneration) return;
543	    result.match((_) {}, (serverMessages) {
544	      ChatMessage? persisted;
545	      for (final m in serverMessages) {
546	        if (m.role == ChatRole.assistant && m.seq == message.seq) {
547	          persisted = m;
548	          break;
549	        }
550	      }
551	      final resolved = persisted;
552	      if (resolved == null ||
553	          resolved.status != ChatMessageStatus.complete ||
554	          resolved.content.isEmpty) {
555	        return;
556	      }
557	      final latest = state;
558	      if (latest is! ChatReady || generation != _turnGeneration) return;
559	      final updated = [
560	        for (final m in latest.messages) if (m.id == assistantId) resolved else m,
561	      ];
562	      emit(latest.copyWith(messages: updated));
563	    });
564	  }
565	
566	  Future<void> _failTurn(
567	    Emitter<ChatState> emit,
568	    String sessionId,
569	    String assistantId,
570	    Failure failure,
571	  ) async {
572	    final latest = state;
573	    if (latest is! ChatReady) return;
574	    emit(_applyFailure(latest, assistantId, failure));
575	    await _onTurnResolved(sessionId, emit);
576	  }
