578	  /// `null` for a retry's `userMessageId` — a retry never targets an
579	  /// optimistic question, only an already-persisted one.
580	  ChatReady _reconcileIds(
581	    ChatReady current,
582	    String? optimisticUserId,
583	    String realUserId,
584	    String optimisticAssistantId,
585	    String realAssistantId,
586	  ) {
587	    final updated = [
588	      for (final m in current.messages)
589	        if (optimisticUserId != null && m.id == optimisticUserId)
590	          _withId(m, realUserId)
591	        else if (m.id == optimisticAssistantId)
592	          _withId(m, realAssistantId)
593	        else
594	          m,
595	    ];
596	    return current.copyWith(messages: updated);
597	  }
