667	  /// Position-matching (research.md R10) — the id of the user message
668	  /// immediately preceding [message] in [messages], or `null` if it isn't
669	  /// immediately preceded by one.
670	  String? _userMessageIdFor(List<ChatMessage> messages, ChatMessage message) {
