709	  Future<void> _onInsightInactivityTimerFired(
710	    InsightInactivityTimerFired event,
711	    Emitter<ChatState> emit,
712	  ) async {
713	    final current = state;
714	    if (current is! ChatReady || current.sessionId == null) return; // research.md R6
715	    if (_insightSuspended) return; // defensive — the timer is cancelled the instant suspension begins
716	    final trigger = InsightTrigger(
717	      type: InsightTriggerType.inactivity,
718	      triggerKey: InsightTriggerKeyBuilder.forInactivity(event.firedAt),
719	    );
