734	  Future<void> _startInsightAttempt(
735	    InsightTrigger trigger, {
736	    required String sessionId,
737	    required Emitter<ChatState> emit,
738	  }) async {
739	    _inactivityTimer?.cancel();
740	    _pendingInsightTrigger = null;
741	    _insightInFlight = true;
742	    final generation = _insightGeneration;
743	    final anchorIndex = (state as ChatReady).messages.length;
744	
745	    if (!await _connectivityChecker.hasConnection()) {
746	      _insightInFlight = false; // FR-007 — never attempted; resolved like a failure
747	      if (generation == _insightGeneration) _armInactivityTimer();
748	      return;
749	    }
750	
751	    final result = await _chatRepository.createInsight(
752	      sessionId: sessionId,
753	      triggerType: trigger.type,
754	      triggerKey: trigger.triggerKey,
755	    );
756	
757	    _insightInFlight = false;
758	    if (generation != _insightGeneration) return; // stale — conversation switched away mid-flight
759	
760	    final latest = state;
761	    if (latest is! ChatReady) return;
762	
763	    result.match(
764	      (failure) {
765	        if (failure is AuthExpiredFailure) _reauthController.add(null);
766	        _armInactivityTimer(); // FR-006 — no card, no indicator; occurrence fully resolved
767	      },
768	      (content) => emit(
769	        latest.copyWith(insight: ProactiveInsight(content: content, anchorIndex: anchorIndex)),
770	      ),
771	    );
772	  }
773	
774	  // Called once per turn resolution — the end of _consumeTurn (after
775	  // _reconcileSilentFailure) and inside _failTurn, both now `Future<void>`.
776	  Future<void> _onTurnResolved(String sessionId, Emitter<ChatState> emit) async {
777	    final hadPending = _pendingInsightTrigger != null;
778	    final trigger = _pendingInsightTrigger;
779	    if (trigger != null) {
780	      final current = state;
781	      if (current is ChatReady && !current.awaitingResponse) {
782	        await _startInsightAttempt(trigger, sessionId: sessionId, emit: emit);
783	      }
784	    }
785	    // Only re-arm here if a deferred trigger just finished resolving without
786	    // a card (failed/skipped) — a turn with no pending trigger leaves
787	    // whatever timer _onMessageSubmitted already armed at send-time alone
788	    // (research.md R4).
789	    if (hadPending && !_insightSuspended) _armInactivityTimer();
790	  }
791	
792	  @override
793	  Future<void> close() {
794	    unawaited(_connectivitySubscription.cancel());
795	    unawaited(_reauthController.close());
796	    _inactivityTimer?.cancel();
797	    return super.close();
798	  }
799	}
