        create: (_) => getIt<RecordsBloc>()..add(const RecordsStarted()),
        child: const RecordsPage(),
      ),
    ),
    GoRoute(
      path: AppRoutes.settings,
      builder: (context, state) => const SettingsPlaceholderPage(),
    ),
  ],
);

